"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["95496"],{24955(e,t,n){n.d(t,{Ay:()=>h,RM:()=>o});var i=n(74848),a=n(28453);let o=[];function s(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"teaching-you-zazen-27-the-fools-of-buddha-recitation-esoteric-practice-and-chan-investigation",children:"Teaching You Zazen 27: The Fools of Buddha-Recitation, Esoteric Practice, and Chan Investigation"})}),"\n",(0,i.jsxs)(t.blockquote,{children:["\n",(0,i.jsx)(t.p,{children:"2008/3/8 11:45:14"}),"\n"]}),"\n",(0,i.jsxs)("div",{style:{color:"#FF0000",fontSize:"18px",fontWeight:"500"},children:[(0,i.jsx)(t.p,{children:"There are such fools who, with diseased eyes producing phantom flowers, call this land a defiled land and that land a pure land, conducting themselves like the sordid affairs of Christianity\u2014yet they do not know that in this Sah\u0101 world, where is the ground not paved with gold, the sky not arrayed with lapis lazuli? With their leaking eyes, how could they discern this?"}),(0,i.jsx)(t.p,{children:"There is no Pure Land in the West, nor is the East a defiled land\u2014all are fabrications of your own mind. To recite the Buddha's name is to truly recite the formless, innately perfect Buddha of one's own nature\u2014not something that billions of lotus-born rebirths could exchange for. Yet the fools who recite the Buddha's name do so through the deluded consciousness of the sixth sense\u2014how could there be any way out?"}),(0,i.jsx)(t.p,{children:"The lotus opens and one sees the Buddha\u2014this is a real matter. But if one clings to this, then even billions of Buddhas appearing in the world could not save them. Without this discernment, one falsely claims to recite the Buddha's name."}),(0,i.jsx)(t.p,{children:"There are such fools who claim to achieve Buddhahood in this very body through esoteric practice\u2014this is nothing but self-deception and deception of others. What they achieve does not even match a fraction of a great Arhat's attainment\u2014how dare they speak of Buddhahood? One body and billions of bodies are merely play within illusion; one lifetime and three great kalpas are merely rehearsals within a dream. To foolishly rank these as superior or inferior\u2014how pitiable, how lamentable."}),(0,i.jsx)(t.p,{children:"There are yet more such fools who claim to achieve Buddhahood through a single awakening in Chan investigation. But when has the Buddha ever been deluded? Without delusion, what need is there for awakening? What you fools call awakening is actually a great mistake. If Chan investigation yields some awakening, it is all the mischief of a mind seeking gain\u2014through awakening one becomes even more deluded. How lamentable, how pitiable."}),(0,i.jsx)(t.p,{children:"Buddha-recitation, esoteric practice, and Chan investigation\u2014each is but one gate among ten thousand Dharma gates. And every path is a Bodhi path, every place a Nirv\u0101\u1E47a gate\u2014how could these be fathomed by your deluded minds of gain and loss, good and evil?"}),(0,i.jsx)(t.p,{children:"The true practitioner becomes all M\u0101ra kings, enters all defiled lands, and achieves realization amid hells and the three evil paths\u2014how could one steal one's heart away by seeking the comfort of a pure land? Rather be born in billions of hells than dwell even a moment in a pure land\u2014this is the true practitioner. Rather spend billions of lifetimes not becoming a Buddha, entering all defiled lands to walk the Bodhisattva path\u2014this is the true practitioner. Rather take billions of bodies as beings in the three evil paths to save those in the three evil paths, than achieve Buddhahood in a single body\u2014this is the true practitioner."}),(0,i.jsx)(t.p,{children:"You can't even become a M\u0101ra king, and you want to become a Buddha? Go dream on."})]})]})}function h(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(s,{...e})}):s(e)}},90371(e,t,n){n.r(t),n.d(t,{metadata:()=>i,default:()=>u,frontMatter:()=>h,contentTitle:()=>r,toc:()=>d,assets:()=>l});var i=JSON.parse('{"id":"timeline/zen/zazen27","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/timeline/zen/zazen27.md","sourceDirName":"timeline/zen","slug":"/timeline/zen/zazen27","permalink":"/en/timeline/zen/zazen27","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"zazen27","title":"","hide_table_of_contents":true,"sidebar_label":"Teaching You Meditation 27: Fools Who Chant Buddha, Practice Esoteric Methods, and Investigate Chan (2008/3/8 11:45:14)"},"sidebar":"timelineSidebar","previous":{"title":"Ping An Should Be Halted to Maintain Market Stability (2008/3/7 15:12:32)","permalink":"/en/timeline/economics/pingansuspension"},"next":{"title":"Following Ping An Closely to Smash the Pot to the Very End (2008/3/10 15:15:31)","permalink":"/en/timeline/economics/followpingan"}}'),a=n(74848),o=n(28453),s=n(24955);let h={id:"zazen27",title:"",hide_table_of_contents:!0,sidebar_label:"Teaching You Meditation 27: Fools Who Chant Buddha, Practice Esoteric Methods, and Investigate Chan (2008/3/8 11:45:14)"},r,l={},d=[...s.RM];function c(e){return(0,a.jsx)(s.Ay,{})}function u(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},28453(e,t,n){n.d(t,{R:()=>s,x:()=>h});var i=n(96540);let a={},o=i.createContext(a);function s(e){let t=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function h(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),i.createElement(o.Provider,{value:t},e.children)}}}]);